import { useCallback, useEffect, useState, type KeyboardEvent } from 'react';
import {
  Add, Apartment, Assessment, CheckCircleOutline, Dashboard as DashboardIcon, DeleteOutline, EditOutlined,
  Groups, Inventory2, LocalHospital, Login, Logout, Menu, MoreHoriz, Search,
  ShoppingCart, SwapHoriz, TrendingUp, Visibility, VisibilityOff, WarningAmber,
} from '@mui/icons-material';
import {
  Alert, Avatar, Box, Button, Checkbox, Chip, CssBaseline, Dialog, DialogActions, DialogContent,
  DialogTitle, Divider, Drawer, IconButton, InputAdornment, Menu as MuiMenu, MenuItem,
  Paper, Pagination, Select, Snackbar, Stack, TextField, ThemeProvider, Typography, createTheme,
} from '@mui/material';
import { Bar, BarChart, CartesianGrid, ResponsiveContainer, Tooltip, XAxis, YAxis } from 'recharts';
import api, { getApiErrorMessage } from './services/api';
import { cpfValido, formatarCpf, formatarTelefone, somenteNumeros, telefoneValido } from './utils/brasil';
import './App.css';
import './profile-menu.css';

type Page = 'dashboard' | 'estoque' | 'pedidos' | 'cadastros' | 'relatorios' | 'usuarios';
type Medicine = { id: string; nome: string; principioAtivo: string; apresentacao: string; estoque: number; minimo: number; maximo: number; validade: string; fornecedor: string; fornecedorId?: string; preco: number; raw?: any };
type OrderStatus = 'Pendente' | 'Em análise' | 'Aprovado' | 'Em entrega' | 'Entregue' | 'Cancelado';
type Order = { id: string; unidade: string; medicamento: string; medicamentoId: string; quantidade: number; data: string; status: OrderStatus; raw?: any };
type Entity = { id: string; nome: string; detalhe: string; status: boolean; raw?: any };
type Role = { id: string; nome: string; descricao: string };
type PermissionValue = { chave: string; modulo: string; acao: string; nome: string; permitido: boolean };
type AuditLog = { id: string; createdAt: string; usuarioNome?: string; usuarioEmail?: string; acao: string; modulo: string; recurso?: string; recursoId?: string; descricao: string; ip?: string; sucesso: boolean; dadosAntes?: any; dadosDepois?: any };
type User = { id: string; nome: string; email: string; funcao: string; roleId: string | null; status: boolean; raw?: any };
type Modal = 'medicine' | 'movement' | 'order' | 'entity' | 'user' | null;

const roles: Role[] = [
  { id: 'SUPER_ADMIN', nome: 'Super administrador', descricao: 'Acesso total e protegido do sistema.' },
  { id: 'ADMIN', nome: 'Administrador', descricao: 'Acesso completo à plataforma.' },
  { id: 'GESTOR', nome: 'Gestor', descricao: 'Opera estoque e acompanha pedidos.' },
  { id: 'FARMACEUTICO', nome: 'Farmacêutico', descricao: 'Consulta e movimenta medicamentos.' },
  { id: 'ATENDENTE', nome: 'Atendente', descricao: 'Registra solicitações e consulta o estoque.' },
  { id: 'CONSULTOR', nome: 'Consultor', descricao: 'Acesso de consulta a relatórios.' },
];
const roleLabels = Object.fromEntries(roles.map(role => [role.id, role.nome]));
const orderLabels: Record<string, OrderStatus> = { PENDENTE: 'Pendente', EM_ANALISE: 'Em análise', APROVADO: 'Aprovado', ENVIADO: 'Em entrega', ENTREGUE: 'Entregue', CANCELADO: 'Cancelado' };
const nav = [
  { page: 'dashboard' as Page, label: 'Visão geral', icon: <DashboardIcon /> },
  { page: 'estoque' as Page, label: 'Estoque', icon: <Inventory2 /> },
  { page: 'pedidos' as Page, label: 'Pedidos', icon: <ShoppingCart /> },
  { page: 'cadastros' as Page, label: 'Cadastros', icon: <Apartment /> },
  { page: 'relatorios' as Page, label: 'Relatórios', icon: <Assessment /> },
  { page: 'usuarios' as Page, label: 'Usuários', icon: <Groups /> },
];
const theme = createTheme({ palette: { primary: { main: '#123a88' }, secondary: { main: '#2a6fd6' }, background: { default: '#f4f8ff' } }, typography: { fontFamily: 'Inter, Arial, sans-serif', h4: { fontWeight: 800 }, h5: { fontWeight: 800 } }, shape: { borderRadius: 14 } });
const formatDate = (value?: string | Date | null) => value ? new Date(value).toLocaleDateString('pt-BR') : '—';
const toDateInput = (value?: string | Date | null) => value ? new Date(value).toISOString().slice(0, 10) : '';
const status = (medicine: Medicine) => medicine.estoque <= medicine.minimo / 2 ? 'Crítico' : medicine.estoque <= medicine.minimo ? 'Baixo' : 'Regular';
const normalizeMedicine = (item: any): Medicine => ({ id: item.id, nome: item.nome, principioAtivo: item.principioAtivo || item.nome, apresentacao: [item.concentracao, item.formaFarmaceutica].filter(Boolean).join(' · ') || 'Não informado', estoque: item.quantidadeAtual, minimo: item.quantidadeMinima, maximo: item.quantidadeMaxima, validade: formatDate(item.validade), fornecedor: item.fornecedor?.nome || 'Sem fornecedor', fornecedorId: item.fornecedorId || item.fornecedor?.id, preco: item.precoUnitario, raw: item });
const normalizeOrder = (item: any): Order => ({ id: item.id, unidade: item.solicitante?.nome || 'Unidade não informada', medicamento: item.medicamentoNome || item.medicamento?.nome, medicamentoId: item.medicamentoId, quantidade: item.quantidadeSolicitada, data: formatDate(item.dataSolicitacao || item.createdAt), status: orderLabels[item.status] || 'Pendente', raw: item });
const normalizeSupplier = (item: any): Entity => ({ id: item.id, nome: item.nome, detalhe: [item.cidade && item.uf ? `${item.cidade}, ${item.uf}` : item.cidade, item.prazoEntrega ? `Prazo médio: ${item.prazoEntrega} dias` : null].filter(Boolean).join(' · ') || 'Sem detalhes', status: item.ativo, raw: item });
const normalizeUnit = (item: any): Entity => ({ id: item.id, nome: item.nome, detalhe: [item.tipo, item.codigo, item.cidade && item.uf ? `${item.cidade}, ${item.uf}` : item.cidade].filter(Boolean).join(' · '), status: item.ativo, raw: item });
const normalizeUser = (item: any): User => ({ id: item.id, nome: item.nome, email: item.email, funcao: roleLabels[item.role] || item.role, roleId: item.role || null, status: item.ativo, raw: item });

function App() {
  const [logged, setLogged] = useState(Boolean(sessionStorage.getItem('token')));
  const [currentUser, setCurrentUser] = useState<any>(() => { try { return JSON.parse(sessionStorage.getItem('user') || 'null'); } catch { return null; } });
  const [page, setPage] = useState<Page>('dashboard');
  const [mobile, setMobile] = useState(false);
  const [medicines, setMedicines] = useState<Medicine[]>([]);
  const [orders, setOrders] = useState<Order[]>([]);
  const [suppliers, setSuppliers] = useState<Entity[]>([]);
  const [units, setUnits] = useState<Entity[]>([]);
  const [users, setUsers] = useState<User[]>([]);
  const [modal, setModal] = useState<Modal>(null);
  const [editing, setEditing] = useState<any>(null);
  const [catalog, setCatalog] = useState<'fornecedores' | 'unidades'>('fornecedores');
  const [toast, setToast] = useState('');
  const [profileAnchor, setProfileAnchor] = useState<HTMLElement | null>(null);
  const [permissions, setPermissions] = useState<string[]>([]);
  const show = (message: string) => setToast(message);
  const open = (kind: Modal, item: any = null) => { setEditing(item); setModal(kind); };
  const loadData = useCallback(async () => {
    if (!sessionStorage.getItem('token')) return;
    try {
      const [meds, ords, supplierResult, unitResult, userResult] = await Promise.all([
        api.get('/medicamentos').catch(() => ({ data: [] })), api.get('/pedidos').catch(() => ({ data: [] })), api.get('/fornecedores').catch(() => ({ data: [] })), api.get('/unidades-saude').catch(() => ({ data: [] })), api.get('/usuarios').catch(() => ({ data: [] })),
      ]);
      setMedicines(meds.data.map(normalizeMedicine)); setOrders(ords.data.map(normalizeOrder)); setSuppliers(supplierResult.data.map(normalizeSupplier)); setUnits(unitResult.data.map(normalizeUnit)); setUsers(userResult.data.map(normalizeUser));
    } catch (error: unknown) { show(getApiErrorMessage(error, 'Não foi possível carregar os dados da operação.')); }
  }, []);
  useEffect(() => { if (logged) loadData(); }, [logged, loadData]);
  const loadPermissions = useCallback(async () => { if (!sessionStorage.getItem('token')) return; try { const { data } = await api.get('/permissoes/minhas'); setPermissions(data); } catch { setPermissions([]); } }, []);
  useEffect(() => { if (logged) loadPermissions(); }, [logged, loadPermissions]);
  const canPage = (target: Page) => { if (currentUser?.role === 'ADMIN' || currentUser?.role === 'SUPER_ADMIN' || permissions.length === 0) return true; const required = ({ dashboard: 'dashboard.visualizar', estoque: 'estoque.visualizar', pedidos: 'pedidos.visualizar', cadastros: ['fornecedores.visualizar', 'unidades.visualizar'], relatorios: 'relatorios.visualizar', usuarios: 'usuarios.visualizar' } as Record<Page, string | string[]>)[target]; return Array.isArray(required) ? required.some(permission => permissions.includes(permission)) : permissions.includes(required); };
  useEffect(() => { if (logged && permissions.length > 0 && !canPage(page)) setPage('dashboard'); }, [logged, permissions, page, currentUser?.role]);
  const handleLogin = async (email: string, senha: string) => { const { data } = await api.post('/auth/login', { email, senha }); sessionStorage.setItem('token', data.access_token); sessionStorage.setItem('user', JSON.stringify(data.usuario)); setCurrentUser(data.usuario); setLogged(true); };
  const handleRegister = async (payload: { nome: string; email: string; cpf: string; senha: string; telefone?: string; cargo?: string }) => { const { data } = await api.post('/auth/register', payload); return data; };
  const logout = async () => { try { if (sessionStorage.getItem('token')) await api.post('/auth/logout'); } catch { /* logout local continua mesmo se a API estiver indisponível */ } finally { sessionStorage.removeItem('token'); sessionStorage.removeItem('user'); setLogged(false); setCurrentUser(null); setPermissions([]); setMedicines([]); setOrders([]); } };
  const saveMedicine = async (form: FormData) => { const estoque = Number(form.get('estoque')); const minimo = Number(form.get('minimo')); const payload = { nome: String(form.get('nome')), principioAtivo: String(form.get('principioAtivo') || form.get('nome')), concentracao: String(form.get('concentracao') || ''), formaFarmaceutica: String(form.get('formaFarmaceutica') || ''), lote: String(form.get('lote') || ''), validade: new Date(`${String(form.get('validade'))}T00:00:00.000Z`), quantidadeAtual: estoque, quantidadeMinima: minimo, quantidadeMaxima: Number(form.get('maximo') || Math.max(estoque, minimo * 2)), precoUnitario: Number(form.get('preco')), fornecedorId: String(form.get('fornecedorId') || '') || undefined }; if (editing) await api.patch(`/medicamentos/${editing.id}`, payload); else await api.post('/medicamentos', payload); await loadData(); setModal(null); show(editing ? 'Medicamento atualizado.' : 'Medicamento adicionado ao estoque.'); };
  const saveOrder = async (form: FormData) => { await api.post('/pedidos', { medicamentoId: String(form.get('medicamentoId')), quantidadeSolicitada: Number(form.get('quantidade')), dataPrevistaEntrega: new Date(`${String(form.get('dataPrevistaEntrega'))}T00:00:00.000Z`), justificativa: String(form.get('justificativa') || '') }); await loadData(); setModal(null); show('Pedido criado com sucesso.'); };
  const saveEntity = async (form: FormData) => { if (catalog === 'fornecedores') { const payload = { nome: String(form.get('nome')), cnpj: String(form.get('cnpj') || editing?.raw?.cnpj || `PENDENTE-${Date.now()}`), cidade: String(form.get('cidade') || ''), uf: String(form.get('uf') || ''), prazoEntrega: Number(form.get('prazoEntrega') || 7), ativo: true }; if (editing) await api.patch(`/fornecedores/${editing.id}`, payload); else await api.post('/fornecedores', payload); } else { const payload = { nome: String(form.get('nome')), codigo: String(form.get('codigo') || editing?.raw?.codigo || `UN-${Date.now()}`), tipo: String(form.get('tipo') || 'UBS'), cidade: String(form.get('cidade') || ''), uf: String(form.get('uf') || ''), ativo: true }; if (editing) await api.patch(`/unidades-saude/${editing.id}`, payload); else await api.post('/unidades-saude', payload); } await loadData(); setModal(null); show('Cadastro salvo.'); };
  const saveUser = async (form: FormData) => { const payload: any = { nome: String(form.get('nome')), email: String(form.get('email')), cpf: String(form.get('cpf') || editing?.raw?.cpf || `PENDENTE-${Date.now()}`), role: String(form.get('roleId') || 'ATENDENTE'), telefone: String(form.get('telefone') || ''), cargo: String(form.get('cargo') || '') }; if (!editing) payload.senha = String(form.get('senha') || 'senha-inicial'); if (editing) await api.patch(`/usuarios/${editing.id}`, payload); else await api.post('/usuarios', payload); await loadData(); setModal(null); show('Usuário salvo.'); };
  const toggleUserStatus = async (user: User) => { try { await api.patch(`/usuarios/${user.id}/toggle`, { ativo: !user.status }); await loadData(); show(user.status ? 'Usuário desativado.' : 'Cadastro aprovado. Usuário liberado para login.'); } catch (error: unknown) { show(getApiErrorMessage(error, 'Não foi possível atualizar o acesso.')); } };
  const remove = async (id: string, endpoint: string, label: string) => { try { await api.delete(`${endpoint}/${id}`); await loadData(); show(`${label} removido.`); } catch (error: unknown) { show(getApiErrorMessage(error, `Não foi possível remover ${label.toLowerCase()}.`)); } };
  const advanceOrder = async (order: Order) => { try { if (order.status === 'Pendente') await api.patch(`/pedidos/${order.id}/aprovar`); else if (order.status === 'Aprovado' || order.status === 'Em entrega') await api.patch(`/pedidos/${order.id}/entregar`, { quantidade: order.quantidade }); else return; await loadData(); show('Status do pedido atualizado.'); } catch (error: unknown) { show(getApiErrorMessage(error, 'Não foi possível atualizar o pedido.')); } };
  const content = () => { if (page === 'dashboard') return <DashboardView medicines={medicines} orders={orders} onGo={setPage} />; if (page === 'estoque') return <StockView medicines={medicines} open={open} remove={(id: string) => remove(id, '/medicamentos', 'Medicamento')} />; if (page === 'pedidos') return <OrdersView orders={orders} open={open} onAdvance={advanceOrder} />; if (page === 'cadastros') return <CatalogView catalog={catalog} setCatalog={setCatalog} items={catalog === 'fornecedores' ? suppliers : units} open={open} remove={(id: string) => remove(id, catalog === 'fornecedores' ? '/fornecedores' : '/unidades-saude', 'Cadastro')} />; if (page === 'relatorios') return <ReportsView medicines={medicines} orders={orders} show={show} />; return <UsersAdminView users={users} roles={roles} open={open} remove={(id: string) => remove(id, '/usuarios', 'Usuário')} onToggleStatus={toggleUserStatus} />; };
  if (!logged) return <ThemeProvider theme={theme}><CssBaseline /><AuthScreen onLogin={handleLogin} onRegister={handleRegister} /></ThemeProvider>;
  const initials = String(currentUser?.nome || 'U').split(' ').map((value: string) => value[0]).slice(0, 2).join('').toUpperCase();
  return <ThemeProvider theme={theme}><CssBaseline /><Box className="app-shell"><Sidebar page={page} setPage={setPage} mobile={mobile} setMobile={setMobile} onLogout={logout} permissions={permissions} role={currentUser?.role} /><Box className="workspace"><header className="topbar"><IconButton className="mobile-menu" onClick={() => setMobile(true)}><Menu /></IconButton><Box><Typography variant="h6">Olá, {currentUser?.nome || 'usuário'} <span>👋</span></Typography><Typography variant="body2" color="text.secondary">Acompanhe a operação da rede municipal</Typography></Box><Stack direction="row" spacing={1.5} alignItems="center"><IconButton aria-label="Abrir menu do perfil" onClick={(event) => setProfileAnchor(event.currentTarget)}><Avatar className="profile">{initials}</Avatar></IconButton></Stack></header><main className="content">{content()}</main></Box></Box><MuiMenu anchorEl={profileAnchor} open={Boolean(profileAnchor)} onClose={() => setProfileAnchor(null)} anchorOrigin={{ vertical: 'bottom', horizontal: 'right' }} transformOrigin={{ vertical: 'top', horizontal: 'right' }} PaperProps={{ className: 'profile-menu' }}><Box className="profile-menu-header"><Avatar className="profile">{initials}</Avatar><Box><Typography fontWeight={800}>{currentUser?.nome || 'Usuário'}</Typography><Typography variant="body2" color="text.secondary">{roleLabels[currentUser?.role] || currentUser?.role || 'Usuário'}</Typography></Box></Box><Divider /><MenuItem onClick={() => { setProfileAnchor(null); show('Os dados do perfil são gerenciados pelo administrador.'); }}>Meu perfil</MenuItem><Divider /><MenuItem onClick={() => { setProfileAnchor(null); logout(); }}>Sair</MenuItem></MuiMenu><AppDialog modal={modal} editing={editing} catalog={catalog} medicines={medicines} suppliers={suppliers} roles={roles} onClose={() => setModal(null)} onMedicine={saveMedicine} onOrder={saveOrder} onEntity={saveEntity} onUser={saveUser} onMovement={async (form: FormData) => { try { await api.patch(`/medicamentos/${editing.id}/estoque`, { quantidade: Number(form.get('quantidade')), tipo: String(form.get('tipo')) === 'Entrada' ? 'ENTRADA' : 'SAIDA' }); await loadData(); setModal(null); show('Movimentação registrada.'); } catch (error: unknown) { show(getApiErrorMessage(error, 'Não foi possível registrar a movimentação.')); } }} /><Snackbar open={!!toast} autoHideDuration={3200} onClose={() => setToast('')}><Alert severity={toast.includes('não') || toast.includes('invál') ? 'error' : 'success'}>{toast}</Alert></Snackbar></ThemeProvider>;
}

function AuthScreen({ onLogin, onRegister }: { onLogin: (email: string, senha: string) => Promise<void>; onRegister: (payload: { nome: string; email: string; cpf: string; senha: string; telefone?: string; cargo?: string }) => Promise<any> }) {
  const [mode, setMode] = useState<'login' | 'register'>('login');
  const [form, setForm] = useState({ nome: '', email: '', cpf: '', senha: '', confirmarSenha: '', telefone: '', cargo: '' });
  const [error, setError] = useState('');
  const [success, setSuccess] = useState('');
  const [submitting, setSubmitting] = useState(false);
  const [passwordVisible, setPasswordVisible] = useState(false);
  const [confirmationVisible, setConfirmationVisible] = useState(false);
  const update = (field: keyof typeof form) => (event: any) => {
    const value = field === 'cpf'
      ? formatarCpf(event.target.value)
      : field === 'telefone'
        ? formatarTelefone(event.target.value)
        : event.target.value;
    setForm(current => ({ ...current, [field]: value }));
  };
  const changeMode = (next: 'login' | 'register') => { setMode(next); setError(''); setSuccess(''); };
  const submit = async () => {
    setSubmitting(true); setError('');
    try {
      if (mode === 'login') { await onLogin(form.email, form.senha); return; }
      if (!form.nome || !form.email || !form.cpf || !form.senha) { setError('Preencha nome, e-mail, CPF e senha.'); return; }
      if (!cpfValido(form.cpf)) { setError('Informe um CPF válido.'); return; }
      if (form.telefone && !telefoneValido(form.telefone)) { setError('Informe um telefone brasileiro válido.'); return; }
      if (form.senha.length < 6) { setError('A senha precisa ter pelo menos 6 caracteres.'); return; }
      if (form.senha !== form.confirmarSenha) { setError('As senhas não conferem.'); return; }
      await onRegister({ nome: form.nome, email: form.email, cpf: somenteNumeros(form.cpf), senha: form.senha, telefone: form.telefone ? somenteNumeros(form.telefone) : undefined, cargo: form.cargo || undefined });
      setSuccess('Cadastro enviado. Aguarde a aprovação do administrador geral para entrar.');
      setForm(current => ({ ...current, senha: '', confirmarSenha: '' }));
    } catch (value: unknown) { setError(getApiErrorMessage(value, 'Não foi possível concluir o cadastro.')); }
    finally { setSubmitting(false); }
  };
  const passwordField = <TextField fullWidth label="Senha" value={form.senha} onChange={update('senha')} type={passwordVisible ? 'text' : 'password'} margin="normal" autoComplete={mode === 'login' ? 'current-password' : 'new-password'} InputProps={{ endAdornment: <InputAdornment position="end"><IconButton aria-label={passwordVisible ? 'Ocultar senha' : 'Mostrar senha'} onClick={() => setPasswordVisible(value => !value)} edge="end"><>{passwordVisible ? <VisibilityOff /> : <Visibility />}</></IconButton></InputAdornment> }} onKeyDown={event => { if (event.key === 'Enter') submit(); }} />;
  const confirmationField = <TextField fullWidth label="Confirmar senha" value={form.confirmarSenha} onChange={update('confirmarSenha')} type={confirmationVisible ? 'text' : 'password'} margin="normal" autoComplete="new-password" InputProps={{ endAdornment: <InputAdornment position="end"><IconButton aria-label={confirmationVisible ? 'Ocultar confirmação de senha' : 'Mostrar confirmação de senha'} onClick={() => setConfirmationVisible(value => !value)} edge="end"><>{confirmationVisible ? <VisibilityOff /> : <Visibility />}</></IconButton></InputAdornment> }} onKeyDown={event => { if (event.key === 'Enter') submit(); }} />;
  return <Box className="login"><Paper className="login-card"><Box className="login-copy"><Box className="logo"><LocalHospital /> S.A.M.</Box><Typography variant="h3">Gestão que cuida de pessoas.</Typography><Typography>Controle de medicamentos, abastecimento e decisões mais rápidas para a saúde pública.</Typography><Box className="login-points"><span>✓ Estoque em tempo real</span><span>✓ Alertas inteligentes</span><span>✓ Dados seguros e organizados</span></Box></Box><Box className="login-form"><Typography variant="h5" mt={2}>{mode === 'login' ? 'Acesse o S.A.M.' : 'Solicite seu acesso'}</Typography><Typography color="text.secondary" mb={2}>{mode === 'login' ? 'Use suas credenciais para consultar os dados da rede.' : 'Após o envio, o administrador geral revisará e liberará seu acesso.'}</Typography>{mode === 'register' ? <><TextField fullWidth label="Nome completo" value={form.nome} onChange={update('nome')} margin="normal" autoComplete="name" /><TextField fullWidth label="E-mail institucional" value={form.email} onChange={update('email')} margin="normal" type="email" autoComplete="email" /><Box className="form-grid"><TextField fullWidth label="CPF" value={form.cpf} onChange={update('cpf')} margin="normal" /><TextField fullWidth label="Telefone" value={form.telefone} onChange={update('telefone')} margin="normal" /></Box><Box className="form-grid"><TextField fullWidth label="Cargo" value={form.cargo} onChange={update('cargo')} margin="normal" /><Box /></Box>{passwordField}{confirmationField}</> : <><TextField fullWidth label="E-mail" value={form.email} onChange={update('email')} margin="normal" type="email" autoComplete="email" />{passwordField}</>}{error && <Alert severity="error" sx={{ mt: 1 }}>{error}</Alert>}{success && <Alert severity="success" sx={{ mt: 1 }}>{success}</Alert>}<Button fullWidth size="large" variant="contained" startIcon={mode === 'login' ? <Login /> : <Add />} onClick={submit} disabled={submitting || (mode === 'login' ? !form.email || !form.senha : false)} sx={{ mt: 2 }}>{submitting ? 'Enviando…' : mode === 'login' ? 'Entrar' : 'Enviar cadastro'}</Button><Button fullWidth variant="text" onClick={() => changeMode(mode === 'login' ? 'register' : 'login')} sx={{ mt: 1 }}>{mode === 'login' ? 'Ainda não tenho acesso — criar cadastro' : 'Já tenho acesso — voltar para login'}</Button></Box></Paper></Box>;
}
function Sidebar({ page, setPage, mobile, setMobile, onLogout, permissions = [], role }: any) { const pagePermission: Record<string, string | string[]> = { dashboard: 'dashboard.visualizar', estoque: 'estoque.visualizar', pedidos: 'pedidos.visualizar', cadastros: ['fornecedores.visualizar', 'unidades.visualizar'], relatorios: 'relatorios.visualizar', usuarios: 'usuarios.visualizar' }; const can = (item: any) => { if (role === 'ADMIN' || role === 'SUPER_ADMIN') return true; const required = pagePermission[item.page]; return Array.isArray(required) ? required.some(permission => permissions.includes(permission)) : permissions.includes(required); }; const inner = <><Box className="brand"><LocalHospital /> <span>S.A.M.</span></Box><Typography className="nav-caption">OPERAÇÃO</Typography>{nav.filter(can).map(item => <Button key={item.page} className={`nav-button ${page === item.page ? 'selected' : ''}`} startIcon={item.icon} onClick={() => { setPage(item.page); setMobile(false); }}>{item.label}</Button>)}<Box flex={1} /><Divider /><Button className="nav-button" startIcon={<Logout />} onClick={onLogout}>Sair</Button></>; return <><aside className="sidebar">{inner}</aside><Drawer open={mobile} onClose={() => setMobile(false)}><Box className="drawer">{inner}</Box></Drawer></>; }
function Header({ eyebrow, title, children }: any) { return <Box className="page-header"><Box><Typography className="eyebrow">{eyebrow}</Typography><Typography variant="h4">{title}</Typography></Box>{children}</Box>; }
function StatusChip({ label }: { label: string }) { return <Chip size="small" label={label} className={`chip chip-${label.toLowerCase().replaceAll(' ', '-')}`} />; }
function Metric({ icon, label, value, change, amber, medicines = [], orders = [] }: any) { const [detailsOpen, setDetailsOpen] = useState(false); const interactive = ['Itens em estoque', 'Alertas ativos', 'Pedidos em aberto', 'Valor em estoque'].includes(label); const alerts = medicines.filter((medicine: Medicine) => status(medicine) !== 'Regular'); const openOrders = orders.filter((order: Order) => !['Entregue', 'Cancelado'].includes(order.status)); const handleKeyDown = (event: KeyboardEvent) => { if (interactive && (event.key === 'Enter' || event.key === ' ')) { event.preventDefault(); setDetailsOpen(true); } }; return <><Paper className={`metric ${amber ? 'metric-warning' : 'metric-positive'} ${interactive ? 'metric-clickable' : ''}`} onClick={interactive ? () => setDetailsOpen(true) : undefined} onKeyDown={handleKeyDown} tabIndex={interactive ? 0 : undefined} role={interactive ? 'button' : undefined}><Box className="metric-icon">{icon}</Box><Typography color="text.secondary" variant="body2">{label}</Typography><Typography variant="h4">{value}</Typography>{change && <Typography className="metric-change">{change}</Typography>}</Paper><Dialog open={detailsOpen} onClose={() => setDetailsOpen(false)} fullWidth maxWidth="sm"><DialogTitle>{label === 'Alertas ativos' ? 'Alertas ativos de estoque' : label}</DialogTitle><DialogContent>{label === 'Alertas ativos' && (alerts.length === 0 ? <Typography color="text.secondary" sx={{ py: 3 }}>Não há alertas ativos no momento.</Typography> : <Stack spacing={1.5} sx={{ pt: 1 }}>{alerts.map((medicine: Medicine) => <Box className="alert-modal-row" key={medicine.id}><Box flex={1}><Typography fontWeight={800}>{medicine.nome}</Typography><Typography variant="body2" color="text.secondary">Estoque atual: {medicine.estoque} un. · mínimo: {medicine.minimo} un.</Typography></Box><StatusChip label={status(medicine)} /></Box>)}</Stack>)}{label === 'Itens em estoque' && <Stack spacing={1.5} sx={{ pt: 1 }}>{medicines.length === 0 ? <Typography color="text.secondary" sx={{ py: 3 }}>Nenhum medicamento disponível.</Typography> : medicines.map((medicine: Medicine) => <Box className="alert-modal-row" key={medicine.id}><Box flex={1}><Typography fontWeight={800}>{medicine.nome}</Typography><Typography variant="body2" color="text.secondary">{medicine.apresentacao}</Typography></Box><Typography fontWeight={800}>{medicine.estoque.toLocaleString('pt-BR')} un.</Typography></Box>)}</Stack>}{label === 'Pedidos em aberto' && <Stack spacing={1.5} sx={{ pt: 1 }}>{openOrders.length === 0 ? <Typography color="text.secondary" sx={{ py: 3 }}>Nenhum pedido em aberto.</Typography> : openOrders.map((order: Order) => <Box className="alert-modal-row" key={order.id}><Box flex={1}><Typography fontWeight={800}>{order.medicamento}</Typography><Typography variant="body2" color="text.secondary">{order.unidade} · {order.quantidade} un.</Typography></Box><StatusChip label={order.status} /></Box>)}</Stack>}{label === 'Valor em estoque' && <Stack spacing={1.5} sx={{ pt: 1 }}>{medicines.length === 0 ? <Typography color="text.secondary" sx={{ py: 3 }}>Nenhum medicamento disponível.</Typography> : medicines.map((medicine: Medicine) => <Box className="alert-modal-row" key={medicine.id}><Box flex={1}><Typography fontWeight={800}>{medicine.nome}</Typography><Typography variant="body2" color="text.secondary">{medicine.estoque.toLocaleString('pt-BR')} unidades</Typography></Box><Typography fontWeight={800}>{(medicine.estoque * medicine.preco).toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' })}</Typography></Box>)}</Stack>}</DialogContent><DialogActions><Button onClick={() => setDetailsOpen(false)}>Fechar</Button></DialogActions></Dialog></>; }
function DashboardView({ medicines, orders, onGo }: any) { const low = medicines.filter((medicine: Medicine) => status(medicine) !== 'Regular'); const value = medicines.reduce((sum: number, medicine: Medicine) => sum + medicine.estoque * medicine.preco, 0); const chart = medicines.slice(0, 6).map((medicine: Medicine) => ({ nome: medicine.nome.split(' ')[0], estoque: medicine.estoque })); return <><Header eyebrow="PAINEL OPERACIONAL" title="Visão geral da rede"><Button variant="contained" startIcon={<Add />} onClick={() => onGo('pedidos')}>Novo pedido</Button></Header><Box className="metric-grid"><Metric medicines={medicines} orders={orders} icon={<Inventory2 />} label="Itens em estoque" value={medicines.reduce((sum: number, medicine: Medicine) => sum + medicine.estoque, 0).toLocaleString('pt-BR')} change="Dados atuais" /><Metric medicines={medicines} orders={orders} icon={<WarningAmber />} label="Alertas ativos" value={low.length} change="Requerem atenção" amber /><Metric medicines={medicines} orders={orders} icon={<ShoppingCart />} label="Pedidos em aberto" value={orders.filter((order: Order) => !['Entregue', 'Cancelado'].includes(order.status)).length} change="Fluxo da rede" /><Metric medicines={medicines} orders={orders} icon={<TrendingUp />} label="Valor em estoque" value={value.toLocaleString('pt-BR', { style: 'currency', currency: 'BRL', maximumFractionDigits: 0 })} /></Box><Box className="dashboard-grid"><Paper className="panel chart-panel"><Box className="panel-title"><Box><Typography variant="h6">Estoque por medicamento</Typography><Typography variant="body2" color="text.secondary">Dados atuais da base operacional</Typography></Box><MoreHoriz /></Box><ResponsiveContainer width="100%" height={290}><BarChart data={chart}><CartesianGrid vertical={false} stroke="#e5eeee" /><XAxis dataKey="nome" axisLine={false} tickLine={false} /><YAxis axisLine={false} tickLine={false} /><Tooltip /><Bar dataKey="estoque" fill="#4f46e5" radius={[5, 5, 0, 0]} /></BarChart></ResponsiveContainer></Paper><Paper className="panel"><Box className="panel-title"><Box><Typography variant="h6">Alertas de estoque</Typography><Typography variant="body2" color="text.secondary">Itens abaixo do nível ideal</Typography></Box><Button size="small" onClick={() => onGo('estoque')}>Ver estoque</Button></Box>{low.length === 0 && <Typography color="text.secondary">Nenhum alerta ativo.</Typography>}{low.map((medicine: Medicine) => <Box className="alert-row" key={medicine.id}><Avatar className={status(medicine) === 'Crítico' ? 'red-avatar' : 'orange-avatar'}><WarningAmber /></Avatar><Box flex={1}><Typography fontWeight={700}>{medicine.nome}</Typography><Typography variant="body2" color="text.secondary">{medicine.estoque} un. disponíveis · mínimo {medicine.minimo}</Typography></Box><StatusChip label={status(medicine)} /></Box>)}</Paper></Box><Paper className="panel"><Box className="panel-title"><Box><Typography variant="h6">Pedidos recentes</Typography><Typography variant="body2" color="text.secondary">Solicitações da rede municipal</Typography></Box><Button size="small" onClick={() => onGo('pedidos')}>Ver todos</Button></Box><SimpleTable headings={['Unidade solicitante', 'Medicamento', 'Quantidade', 'Status']} rows={orders.slice(0, 8).map((order: Order) => [order.unidade, order.medicamento, `${order.quantidade} un.`, <StatusChip label={order.status} />])} /></Paper></>; }
function StockView({ medicines, open, remove }: any) { const [query, setQuery] = useState(''); const list = medicines.filter((medicine: Medicine) => medicine.nome.toLowerCase().includes(query.toLowerCase())); return <><Header eyebrow="GESTÃO DE INSUMOS" title="Estoque de medicamentos"><Button variant="contained" startIcon={<Add />} onClick={() => open('medicine')}>Adicionar medicamento</Button></Header><Paper className="panel"><Box className="toolbar"><TextField size="small" placeholder="Buscar medicamento..." value={query} onChange={event => setQuery(event.target.value)} InputProps={{ startAdornment: <InputAdornment position="start"><Search /></InputAdornment> }} /><Typography variant="body2" color="text.secondary">{list.length} itens encontrados</Typography></Box><div className="table-wrap"><SimpleTable headings={['Medicamento', 'Estoque atual', 'Cobertura', 'Validade', 'Status', 'Ações']} rows={list.map((medicine: Medicine) => [<Box><Typography fontWeight={700}>{medicine.nome}</Typography><Typography variant="body2" color="text.secondary">{medicine.apresentacao}</Typography></Box>, `${medicine.estoque.toLocaleString('pt-BR')} un.`, <Box className="coverage"><Box><span style={{ width: `${Math.min(100, medicine.minimo ? medicine.estoque / medicine.minimo * 50 : 100)}%` }} /></Box><small>{medicine.minimo ? Math.round(medicine.estoque / medicine.minimo * 30) : 0} dias</small></Box>, medicine.validade, <StatusChip label={status(medicine)} />, <Stack direction="row"><IconButton size="small" onClick={() => open('movement', medicine)}><SwapHoriz /></IconButton><IconButton size="small" onClick={() => open('medicine', medicine)}><EditOutlined /></IconButton><IconButton size="small" color="error" onClick={() => remove(medicine.id)}><DeleteOutline /></IconButton></Stack>])} /></div></Paper></>; }
function OrdersView({ orders, open, onAdvance }: any) { const [filter, setFilter] = useState('Todos'); const list = filter === 'Todos' ? orders : orders.filter((order: Order) => order.status === filter); return <><Header eyebrow="REPOSIÇÃO E DISTRIBUIÇÃO" title="Pedidos da rede"><Button variant="contained" startIcon={<Add />} onClick={() => open('order')}>Novo pedido</Button></Header><Paper className="panel"><Box className="toolbar"><Select size="small" value={filter} onChange={event => setFilter(String(event.target.value))}>{['Todos', 'Pendente', 'Em análise', 'Aprovado', 'Em entrega', 'Entregue', 'Cancelado'].map(value => <MenuItem key={value} value={value}>{value}</MenuItem>)}</Select><Typography variant="body2" color="text.secondary">Aprovação e entrega são persistidas no backend</Typography></Box><SimpleTable headings={['Solicitado por', 'Medicamento', 'Quantidade', 'Data', 'Status']} rows={list.map((order: Order) => [order.unidade, order.medicamento, `${order.quantidade} un.`, order.data, <Button size="small" disabled={['Entregue', 'Cancelado'].includes(order.status)} onClick={() => onAdvance(order)}><StatusChip label={order.status} /></Button>])} /></Paper></>; }
function CatalogView({ catalog, setCatalog, items, open, remove }: any) { const label = catalog === 'fornecedores' ? 'Fornecedores' : 'Unidades de saúde'; return <><Header eyebrow="BASE CADASTRAL" title={label}><Button variant="contained" startIcon={<Add />} onClick={() => open('entity')}>Adicionar {catalog === 'fornecedores' ? 'fornecedor' : 'unidade'}</Button></Header><Paper className="panel"><Box className="tabs"><Button className={catalog === 'fornecedores' ? 'tab-selected' : ''} onClick={() => setCatalog('fornecedores')}>Fornecedores</Button><Button className={catalog === 'unidades' ? 'tab-selected' : ''} onClick={() => setCatalog('unidades')}>Unidades de saúde</Button></Box><SimpleTable headings={[catalog === 'fornecedores' ? 'Fornecedor' : 'Unidade', 'Detalhes', 'Status', 'Ações']} rows={items.map((item: Entity) => [<Typography fontWeight={700}>{item.nome}</Typography>, item.detalhe, <Chip label={item.status ? 'Ativo' : 'Inativo'} color={item.status ? 'success' : 'default'} size="small" />, <Stack direction="row"><IconButton size="small" onClick={() => open('entity', item)}><EditOutlined /></IconButton><IconButton size="small" color="error" onClick={() => remove(item.id)}><DeleteOutline /></IconButton></Stack>])} /></Paper></>; }
function ReportsView({ medicines, orders, show }: any) { const [period, setPeriod] = useState('Últimos 30 dias'); const [exporting, setExporting] = useState(false); const exportReport = async (formato: 'PDF' | 'EXCEL', visualizar = false) => { setExporting(true); const preview = visualizar ? window.open('', '_blank') : null; try { const response = await api.post('/relatorios/exportar', { tipo: 'MEDICAMENTOS', formato, dataInicio: new Date(Date.now() - 30 * 86400000).toISOString(), dataFim: new Date().toISOString() }, { responseType: 'blob' }); const url = URL.createObjectURL(response.data); if (visualizar && preview) { preview.location.href = url; show('PDF aberto para visualização.'); setTimeout(() => URL.revokeObjectURL(url), 60000); } else { const link = document.createElement('a'); link.href = url; link.download = `relatorio-sam.${formato === 'PDF' ? 'pdf' : 'xlsx'}`; link.click(); URL.revokeObjectURL(url); show('Relatório exportado.'); } } catch (error: unknown) { preview?.close(); show(getApiErrorMessage(error, 'Não foi possível gerar o relatório.')); } finally { setExporting(false); } }; return <><Header eyebrow="INTELIGÊNCIA OPERACIONAL" title="Relatórios e análises"><Select size="small" value={period} onChange={event => setPeriod(String(event.target.value))}>{['Últimos 30 dias', 'Último trimestre', 'Este ano'].map(value => <MenuItem key={value} value={value}>{value}</MenuItem>)}</Select></Header><Box className="report-grid"><Paper className="panel"><Typography variant="h6">Resumo do período</Typography><Box className="report-number">{orders.reduce((sum: number, order: Order) => sum + order.quantidade, 0).toLocaleString('pt-BR')}<small> unidades solicitadas</small></Box><Divider /><Typography mt={2}>Estoque monitorado: <b>{medicines.length} medicamentos</b></Typography><Typography mt={1}>Pedidos em tratamento: <b>{orders.length}</b></Typography></Paper><Paper className="panel"><Typography variant="h6">Ações de relatório</Typography><Typography color="text.secondary" variant="body2" my={2}>Os arquivos são gerados pelo backend com os dados atuais.</Typography><Stack direction={{ xs: 'column', sm: 'row' }} spacing={1} flexWrap="wrap"><Button variant="outlined" startIcon={<Visibility />} disabled={exporting} onClick={() => exportReport('PDF', true)}>Visualizar PDF</Button><Button variant="outlined" disabled={exporting} onClick={() => exportReport('PDF')}>Exportar PDF</Button><Button variant="outlined" disabled={exporting} onClick={() => exportReport('EXCEL')}>Exportar Excel</Button></Stack></Paper></Box><Paper className="panel"><Typography variant="h6">Indicadores para {period.toLowerCase()}</Typography><Box className="insights"><Insight label="Disponibilidade média" value={medicines.length ? `${Math.round(medicines.filter((medicine: Medicine) => status(medicine) === 'Regular').length / medicines.length * 100)}%` : '—'} /><Insight label="Pedidos atendidos" value={orders.length ? `${Math.round(orders.filter((order: Order) => order.status === 'Entregue').length / orders.length * 100)}%` : '—'} /><Insight label="Itens críticos" value={`${medicines.filter((medicine: Medicine) => status(medicine) === 'Crítico').length}`} /></Box></Paper></>; }
function Insight({ label, value }: any) { return <Box><Typography className="eyebrow">{label}</Typography><Typography variant="h4">{value}</Typography></Box>; }
function UsersView({ users, roles, open, remove, onToggleStatus }: any) { const pending = users.filter((user: User) => !user.status).length; return <><Header eyebrow="ACESSO E GOVERNANÇA" title="Usuários da plataforma"><Stack direction="row" spacing={1} alignItems="center"><Chip label={`${pending} pendente${pending === 1 ? '' : 's'}`} color={pending > 0 ? 'warning' : 'default'} variant={pending > 0 ? 'filled' : 'outlined'} /><Button variant="contained" startIcon={<Add />} onClick={() => open('user')}>Adicionar usuário</Button></Stack></Header><Box className="user-admin-grid"><Paper className="panel"><Box className="panel-title"><Box><Typography variant="h6">Usuários</Typography><Typography variant="body2" color="text.secondary">Cadastros novos ficam pendentes até a aprovação do administrador.</Typography></Box></Box><SimpleTable headings={['Usuário', 'E-mail', 'Função', 'Status', 'Ações']} rows={users.map((user: User) => [<Stack direction="row" spacing={1} alignItems="center"><Avatar>{user.nome.split(' ').map(value => value[0]).slice(0, 2).join('')}</Avatar><Typography fontWeight={700}>{user.nome}</Typography></Stack>, user.email, user.funcao || '—', <Chip label={user.status ? 'Ativo' : 'Pendente'} color={user.status ? 'success' : 'warning'} size="small" />, <Stack direction="row">{!user.status && <IconButton size="small" color="success" aria-label="Aprovar cadastro" onClick={() => onToggleStatus(user)}><CheckCircleOutline /></IconButton>}<IconButton size="small" onClick={() => open('user', user)}><EditOutlined /></IconButton><IconButton size="small" color="error" onClick={() => remove(user.id)}><DeleteOutline /></IconButton></Stack>])} /></Paper><Paper className="panel"><Box className="panel-title"><Box><Typography variant="h6">Funções</Typography><Typography variant="body2" color="text.secondary">Papéis disponíveis no sistema</Typography></Box></Box><Stack spacing={1.5}>{roles.map((role: Role) => <Box className="role-row" key={role.id}><Box flex={1}><Typography fontWeight={800}>{role.nome}</Typography><Typography variant="body2" color="text.secondary">{role.descricao}</Typography></Box><Chip label={role.id} size="small" variant="outlined" /></Box>)}</Stack></Paper></Box></>; }
function SimpleTable({ headings, rows }: any) { return <table><thead><tr>{headings.map((heading: any, index: number) => <th key={index}>{heading}</th>)}</tr></thead><tbody>{rows.map((row: any[], index: number) => <tr key={index}>{row.map((cell: any, cellIndex: number) => <td key={cellIndex}>{cell}</td>)}</tr>)}</tbody></table>; }
function AppDialog({ modal, editing, catalog, medicines, suppliers, roles, onClose, onMedicine, onOrder, onEntity, onUser, onMovement }: any) { const submit = (callback: any) => (event: any) => { event.preventDefault(); callback(new FormData(event.currentTarget)).catch?.(() => undefined); }; const field = (name: string, label: string, value = '', type = 'text', required = true) => <TextField name={name} label={label} defaultValue={value} type={type} fullWidth required={required} margin="dense" />; if (!modal) return null; const title = modal === 'medicine' ? (editing ? 'Editar medicamento' : 'Adicionar medicamento') : modal === 'movement' ? `Movimentar ${editing?.nome}` : modal === 'order' ? 'Novo pedido' : modal === 'entity' ? (editing ? 'Editar cadastro' : `Adicionar ${catalog === 'fornecedores' ? 'fornecedor' : 'unidade'}`) : (editing ? 'Editar usuário' : 'Adicionar usuário'); let body: any; let handler: any; if (modal === 'medicine') { handler = onMedicine; body = <><Box className="form-grid">{field('nome', 'Nome do medicamento', editing?.raw?.nome)}{field('principioAtivo', 'Princípio ativo', editing?.raw?.principioAtivo || editing?.raw?.nome)}</Box><Box className="form-grid">{field('concentracao', 'Concentração', editing?.raw?.concentracao || '', 'text', false)}{field('formaFarmaceutica', 'Forma farmacêutica', editing?.raw?.formaFarmaceutica || editing?.apresentacao || '', 'text', false)}</Box><Box className="form-grid">{field('estoque', 'Estoque atual', editing?.estoque || 0, 'number')}{field('minimo', 'Estoque mínimo', editing?.minimo || 0, 'number')}</Box><Box className="form-grid">{field('validade', 'Validade', toDateInput(editing?.raw?.validade), 'date')}{field('preco', 'Preço unitário', editing?.preco || 0, 'number')}</Box><Select name="fornecedorId" defaultValue={editing?.fornecedorId || ''} fullWidth displayEmpty sx={{ mt: 1 }}><MenuItem value=""><em>Sem fornecedor</em></MenuItem>{suppliers.map((supplier: Entity) => <MenuItem key={supplier.id} value={supplier.id}>{supplier.nome}</MenuItem>)}</Select></>; } else if (modal === 'movement') { handler = onMovement; body = <><Select name="tipo" defaultValue="Entrada" fullWidth sx={{ mt: 1 }}><MenuItem value="Entrada">Entrada</MenuItem><MenuItem value="Saída">Saída</MenuItem></Select>{field('quantidade', 'Quantidade', '', 'number')}</>; } else if (modal === 'order') { handler = onOrder; body = <>{field('dataPrevistaEntrega', 'Previsão de entrega', new Date().toISOString().slice(0, 10), 'date')}{field('quantidade', 'Quantidade solicitada', '', 'number')}{field('justificativa', 'Justificativa', '', 'text', false)}<Select name="medicamentoId" defaultValue={medicines[0]?.id || ''} fullWidth sx={{ mt: 1 }}>{medicines.map((medicine: Medicine) => <MenuItem key={medicine.id} value={medicine.id}>{medicine.nome}</MenuItem>)}</Select></>; } else if (modal === 'entity') { handler = onEntity; body = <>{field('nome', catalog === 'fornecedores' ? 'Nome do fornecedor' : 'Nome da unidade', editing?.nome)}{catalog === 'fornecedores' ? <>{field('cnpj', 'CNPJ', editing?.raw?.cnpj || '', 'text', !editing)}<Box className="form-grid">{field('cidade', 'Cidade', editing?.raw?.cidade || '', 'text', false)}{field('uf', 'UF', editing?.raw?.uf || '', 'text', false)}</Box>{field('prazoEntrega', 'Prazo de entrega (dias)', editing?.raw?.prazoEntrega || 7, 'number', false)}</> : <><Box className="form-grid">{field('codigo', 'Código', editing?.raw?.codigo || '', 'text', !editing)}<Select name="tipo" defaultValue={editing?.raw?.tipo || 'UBS'} fullWidth sx={{ mt: 1 }}><MenuItem value="UBS">UBS</MenuItem><MenuItem value="UPA">UPA</MenuItem><MenuItem value="HOSPITAL">Hospital</MenuItem><MenuItem value="CENTRO_ESPECIALIZADO">Centro especializado</MenuItem><MenuItem value="FARMACIA">Farmácia</MenuItem></Select></Box><Box className="form-grid">{field('cidade', 'Cidade', editing?.raw?.cidade || '', 'text', false)}{field('uf', 'UF', editing?.raw?.uf || '', 'text', false)}</Box></>}</>; } else { handler = onUser; body = <>{field('nome', 'Nome completo', editing?.nome)}{field('email', 'E-mail', editing?.email, 'email')}{field('cpf', 'CPF', editing?.raw?.cpf || '', 'text', !editing)}{!editing && field('senha', 'Senha inicial', '', 'password', true)}<Select name="roleId" defaultValue={editing?.roleId || 'ATENDENTE'} fullWidth sx={{ mt: 1 }}>{roles.filter((role: Role) => role.id !== 'SUPER_ADMIN').map((role: Role) => <MenuItem key={role.id} value={role.id}>{role.nome}</MenuItem>)}</Select></>; } return <Dialog open onClose={onClose} fullWidth maxWidth="sm"><form onSubmit={submit(handler)}><DialogTitle>{title}</DialogTitle><DialogContent>{body}</DialogContent><DialogActions><Button onClick={onClose}>Cancelar</Button><Button variant="contained" type="submit">Salvar</Button></DialogActions></form></Dialog>; }

function UsersAdminView({ users, roles, open, remove, onToggleStatus }: any) {
  const [tab, setTab] = useState<'usuarios' | 'permissoes' | 'historico'>('usuarios');
  const [rolePermissions, setRolePermissions] = useState<any[]>([]);
  const [catalog, setCatalog] = useState<PermissionValue[]>([]);
  const [selectedRole, setSelectedRole] = useState('GESTOR');
  const [history, setHistory] = useState<AuditLog[]>([]);
  const [historyPage, setHistoryPage] = useState(1);
  const [historyTotalPages, setHistoryTotalPages] = useState(1);
  const [historyAction, setHistoryAction] = useState('');
  const [historyModule, setHistoryModule] = useState('');
  const [detail, setDetail] = useState<AuditLog | null>(null);
  const [permissionUser, setPermissionUser] = useState<any>(null);
  const [permissionValues, setPermissionValues] = useState<Record<string, boolean | null>>({});
  const pending = users.filter((user: User) => !user.status).length;
  const editableRoles = roles.filter((role: Role) => !['ADMIN', 'SUPER_ADMIN'].includes(role.id));
  const loadPermissions = async () => { try { const [rolesResponse, catalogResponse] = await Promise.all([api.get('/permissoes/papeis'), api.get('/permissoes/catalogo')]); setRolePermissions(rolesResponse.data); setCatalog(catalogResponse.data); } catch { /* mensagens genéricas são exibidas pelas operações */ } };
  const loadHistory = async (page = historyPage) => { try { const params = new URLSearchParams({ page: String(page), limit: '20' }); if (historyAction) params.set('acao', historyAction); if (historyModule) params.set('modulo', historyModule); const { data } = await api.get(`/auditoria?${params.toString()}`); setHistory(data.data); setHistoryTotalPages(data.meta.totalPages || 1); setHistoryPage(page); } catch { setHistory([]); } };
  useEffect(() => { if (tab === 'permissoes') loadPermissions(); if (tab === 'historico') loadHistory(1); }, [tab]);
  const selectedRoleData = rolePermissions.find((item) => item.role === selectedRole);
  const changeRolePermission = (chave: string, permitido: boolean) => setRolePermissions(current => current.map(item => item.role === selectedRole ? { ...item, permissoes: item.permissoes.map((permission: PermissionValue) => permission.chave === chave ? { ...permission, permitido } : permission) } : item));
  const saveRolePermissions = async () => { if (!selectedRoleData) return; await api.put(`/permissoes/papeis/${selectedRole}`, { permissoes: selectedRoleData.permissoes.map((permission: PermissionValue) => ({ chave: permission.chave, permitido: permission.permitido })) }); };
  const openPermissions = async (user: User) => { try { const { data } = await api.get(`/permissoes/usuarios/${user.id}`); const overrides = Object.fromEntries(data.excecoes.map((item: any) => [item.chave, item.permitido])); setPermissionValues(Object.fromEntries(data.permissoes.map((item: PermissionValue) => [item.chave, overrides[item.chave] ?? null]))); setPermissionUser(user); } catch { setPermissionUser(null); } };
  const saveUserPermissions = async () => { if (!permissionUser) return; await api.put(`/permissoes/usuarios/${permissionUser.id}`, { permissoes: Object.entries(permissionValues).filter(([, value]) => value !== null).map(([chave, permitido]) => ({ chave, permitido })) }); setPermissionUser(null); };
  const exportHistory = async (formato: 'PDF' | 'CSV') => { const params = new URLSearchParams({ formato }); if (historyAction) params.set('acao', historyAction); if (historyModule) params.set('modulo', historyModule); const response = await api.get(`/auditoria/exportar?${params.toString()}`, { responseType: 'blob' }); const url = URL.createObjectURL(response.data); const link = document.createElement('a'); link.href = url; link.download = `historico-auditoria.${formato.toLowerCase()}`; link.click(); URL.revokeObjectURL(url); };
  const pendingChip = <Chip label={`${pending} pendente${pending === 1 ? '' : 's'}`} color={pending > 0 ? 'warning' : 'default'} variant={pending > 0 ? 'filled' : 'outlined'} />;
  return <>
    <Header eyebrow="ACESSO E GOVERNANÇA" title="Usuários da plataforma"><Stack direction="row" spacing={1} alignItems="center">{pendingChip}<Button variant="contained" startIcon={<Add />} onClick={() => open('user')}>Adicionar usuário</Button></Stack></Header>
    <Paper className="panel"><Box className="tabs"><Button className={tab === 'usuarios' ? 'tab-selected' : ''} onClick={() => setTab('usuarios')}>Usuários</Button><Button className={tab === 'permissoes' ? 'tab-selected' : ''} onClick={() => setTab('permissoes')}>Permissões</Button><Button className={tab === 'historico' ? 'tab-selected' : ''} onClick={() => setTab('historico')}>Histórico</Button></Box></Paper>
    {tab === 'usuarios' && <Box className="user-admin-grid"><Paper className="panel"><Box className="panel-title"><Box><Typography variant="h6">Usuários</Typography><Typography variant="body2" color="text.secondary">Cadastros novos ficam pendentes até a aprovação do administrador.</Typography></Box></Box><SimpleTable headings={['Usuário', 'E-mail', 'Função', 'Status', 'Ações']} rows={users.map((user: User) => [<Stack direction="row" spacing={1} alignItems="center"><Avatar>{user.nome.split(' ').map(value => value[0]).slice(0, 2).join('')}</Avatar><Typography fontWeight={700}>{user.nome}</Typography></Stack>, user.email, user.funcao || '—', <Chip label={user.status ? 'Ativo' : 'Pendente'} color={user.status ? 'success' : 'warning'} size="small" />, <Stack direction="row">{!user.status && <IconButton size="small" color="success" aria-label="Aprovar cadastro" onClick={() => onToggleStatus(user)}><CheckCircleOutline /></IconButton>}<IconButton size="small" aria-label="Editar usuário" disabled={user.roleId === 'SUPER_ADMIN'} onClick={() => open('user', user)}><EditOutlined /></IconButton><Button size="small" disabled={user.roleId === 'SUPER_ADMIN'} onClick={() => openPermissions(user)}>Permissões</Button><IconButton size="small" color="error" aria-label="Excluir usuário" disabled={user.roleId === 'SUPER_ADMIN'} onClick={() => remove(user.id)}><DeleteOutline /></IconButton></Stack>])} /></Paper><Paper className="panel"><Box className="panel-title"><Box><Typography variant="h6">Funções</Typography><Typography variant="body2" color="text.secondary">Papéis disponíveis no sistema</Typography></Box></Box><Stack spacing={1.5}>{roles.map((role: Role) => <Box className="role-row" key={role.id}><Box flex={1}><Typography fontWeight={800}>{role.nome}</Typography><Typography variant="body2" color="text.secondary">{role.descricao}</Typography></Box><Chip label={role.id} size="small" variant="outlined" /></Box>)}</Stack></Paper></Box>}
    {tab === 'permissoes' && <Paper className="panel"><Box className="toolbar"><Select size="small" value={selectedRole} onChange={event => setSelectedRole(String(event.target.value))}>{editableRoles.map((role: Role) => <MenuItem key={role.id} value={role.id}>{role.nome}</MenuItem>)}</Select><Button variant="contained" onClick={saveRolePermissions}>Salvar permissões do papel</Button></Box><Typography variant="body2" color="text.secondary" mb={2}>ADMIN e SUPER_ADMIN possuem acesso total e não podem ser limitados por esta matriz.</Typography><Stack spacing={1}>{(selectedRoleData?.permissoes || catalog).map((permission: PermissionValue) => <Box className="permission-row" key={permission.chave}><Checkbox checked={Boolean(permission.permitido)} onChange={event => changeRolePermission(permission.chave, event.target.checked)} /><Typography>{permission.nome}</Typography><Chip size="small" label={permission.chave} variant="outlined" /></Box>)}</Stack></Paper>}
    {tab === 'historico' && <Paper className="panel"><Box className="toolbar"><TextField size="small" label="Ação" value={historyAction} onChange={event => setHistoryAction(event.target.value)} /><TextField size="small" label="Módulo" value={historyModule} onChange={event => setHistoryModule(event.target.value)} /><Button variant="outlined" onClick={() => loadHistory(1)}>Filtrar</Button><Button variant="outlined" onClick={() => exportHistory('CSV')}>Exportar CSV</Button><Button variant="outlined" onClick={() => exportHistory('PDF')}>Exportar PDF</Button></Box><SimpleTable headings={['Data', 'Usuário', 'Ação', 'Módulo', 'Descrição', 'Status', 'Detalhes']} rows={history.map((item) => [new Date(item.createdAt).toLocaleString('pt-BR'), item.usuarioNome || 'Sistema', item.acao, item.modulo, item.descricao, item.sucesso ? 'Sucesso' : 'Falha', <Button size="small" onClick={() => setDetail(item)}>Ver</Button>])} /><Pagination count={historyTotalPages} page={historyPage} onChange={(_, page) => loadHistory(page)} sx={{ mt: 2 }} /></Paper>}
    <Dialog open={Boolean(detail)} onClose={() => setDetail(null)} fullWidth maxWidth="md"><DialogTitle>Detalhes da auditoria</DialogTitle><DialogContent><Typography variant="body2" mb={1}>{detail?.descricao}</Typography><pre style={{ whiteSpace: 'pre-wrap' }}>{JSON.stringify({ antes: detail?.dadosAntes, depois: detail?.dadosDepois, ip: detail?.ip, navegador: detail?.usuarioEmail }, null, 2)}</pre></DialogContent><DialogActions><Button onClick={() => setDetail(null)}>Fechar</Button></DialogActions></Dialog>
    <Dialog open={Boolean(permissionUser)} onClose={() => setPermissionUser(null)} fullWidth maxWidth="md"><DialogTitle>Exceções de permissões — {permissionUser?.nome}</DialogTitle><DialogContent><Typography variant="body2" color="text.secondary" mb={2}>Herdar mantém a configuração do papel; permitir ou bloquear cria uma exceção individual.</Typography><Stack spacing={1}>{Object.entries(permissionValues).map(([chave, value]) => <Box className="permission-row" key={chave}><Typography flex={1}>{chave}</Typography><Select size="small" value={value === null ? 'inherit' : value ? 'allow' : 'deny'} onChange={event => setPermissionValues(current => ({ ...current, [chave]: event.target.value === 'inherit' ? null : event.target.value === 'allow' }))}><MenuItem value="inherit">Herdar do papel</MenuItem><MenuItem value="allow">Permitir</MenuItem><MenuItem value="deny">Bloquear</MenuItem></Select></Box>)}</Stack></DialogContent><DialogActions><Button onClick={() => setPermissionUser(null)}>Cancelar</Button><Button variant="contained" onClick={saveUserPermissions}>Salvar exceções</Button></DialogActions></Dialog>
  </>;
}

export default App;
